/// One step in a component's resolved inheritance chain.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct InheritedLayer {
    /// Type name as declared: "ButtonHTMLAttributes", "ButtonBaseProps", "ThemingProps"
    pub type_name: String,
    /// Absolute path of the file this came from.
    /// "node_modules/@types/react/..." for HTML attrs; project-local path otherwise.
    pub file_name: String,
    /// Props explicitly removed at this layer via Omit<Base, K>.
    pub omitted: Vec<String>,
    /// If this is an HTML element attributes type, the element name: "button", "input", etc.
    pub html_element: Option<String>,
    /// Number of props this layer contributes (for display).
    pub total_props: u32,
    /// For a collapsed source, the names of the props it declares, which the output otherwise leaves out (only the
    /// notable ones are listed as props). Empty for a layer whose props are expanded.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub members: Vec<String>,
}

/// A single React component with its resolved props.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ComponentEntry {
    /// Display name of the component
    pub display_name: String,
    /// Absolute path of the file containing the component
    pub file_path: Utf8PathBuf,
    /// Component-level JSDoc description
    pub description: String,
    /// Resolved props, keyed by prop name. Shared: components that inherit one interface hold the same prop, so change
    /// one through `Arc::make_mut`, which copies it first when another component holds it too.
    pub props: BTreeMap<String, Arc<ParsedProp>>,
    /// Full resolved inheritance chain, outermost first.
    pub inheritance: Vec<InheritedLayer>,
    /// Curated notable props from inherited layers (not in self.props), shared like `props`.
    pub notable_inherited: BTreeMap<String, Arc<ParsedProp>>,
    /// If props type is a discriminated union, the name of the discriminant prop (e.g. "variant").
    pub discriminant_prop: Option<String>,
    /// Type names that could not be resolved (react-docgen compat)
// `__docgenInfo` (react-docgen-typescript's shape) to argTypes, the way `@storybook/react`'s own docgen worker does it
// (src/docgen/buildDocgen.ts): React's `Attributes`, `RefAttributes` and `ClassAttributes` props from node_modules are
// dropped, defaults are marked `computed: false`, and React's `extractArgTypes` converts the rest. Calling React's
// converter, not a copy of it, keeps controls, type summaries and default-value summaries identical to Storybook's.

import type { RdtComponentDoc, RdtProp } from 'caliper-docgen-napi'
import type { StrictArgTypes } from 'storybook/internal/types'

/** `parameters.docs.extractArgTypes` from `@storybook/react/entry-preview-argtypes`. */
export type ExtractArgTypes = (component: { __docgenInfo: RdtComponentDoc }) => StrictArgTypes | null

const REACT_ATTRIBUTE_INTERFACES = new Set(['Attributes', 'RefAttributes', 'ClassAttributes'])

function isReactAttribute(prop: RdtProp): boolean {
  return (
    prop.parent !== null &&
    REACT_ATTRIBUTE_INTERFACES.has(prop.parent.name) &&
    /(^|[\\/])node_modules[\\/]/.test(prop.parent.fileName)
  )
}

export function toArgTypes(doc: RdtComponentDoc, extractArgTypes: ExtractArgTypes): StrictArgTypes | undefined {
  const props = Object.fromEntries(
    Object.entries(doc.props)
      .filter(([, prop]) => !isReactAttribute(prop))
      .map(([name, prop]) => [
        name,
        prop.defaultValue ? { ...prop, defaultValue: { ...prop.defaultValue, computed: false } } : prop,
      ]),
  )
  return extractArgTypes({ __docgenInfo: { ...doc, props } }) ?? undefined
}

/** React's converter, loaded on first use: it is a preview entry, so only a docgen request should pay for it. */
export async function loadExtractArgTypes(): Promise<ExtractArgTypes> {
  const { parameters } = (await import('@storybook/react/entry-preview-argtypes')) as {
    parameters: { docs: { extractArgTypes: ExtractArgTypes } }
  }
  return parameters.docs.extractArgTypes
}

